import fs from "node:fs";

import { USERS, expect, sample, test, uniqueName } from "../../fixtures";

test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Given I am signed in as member@northwind.test
  const member = await apiAs("member");

  // And I created a vendor and uploaded a W-9 for it
  const createRes = await member.post("/api/vendors", {
    data: { name: uniqueName("Audit Vendor"), category: "logistics", contact_email: "ops@audit-vendor.example" },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendor = await createRes.json();

  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: fs.readFileSync(sample("w9.txt")) },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const document = await uploadRes.json();

  // Extraction runs in the background; wait for it to finish.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${document.id}`);
        return (await res.json()).status;
      },
      { timeout: 30_000, message: "document should leave processing" },
    )
    .toBe("extracted");

  // When I request the vendor's audit trail
  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);

  // Then the response status is 200
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const trail = await auditRes.json();
  const items = trail.items as Array<{
    id: number;
    action: string;
    actor: { id: string; name: string; email: string };
    at: string;
  }>;

  // And the actions are in that order
  expect(items.map((e) => e.action), JSON.stringify(trail)).toEqual([
    "vendor.created",
    "document.uploaded",
    "document.extracted",
  ]);

  // And each event names the actor and a timestamp
  let previous = -Infinity;
  for (const event of items) {
    expect(event.actor, JSON.stringify(event)).toBeTruthy();
    expect(event.actor.email, JSON.stringify(event)).toBe(USERS.member);
    expect(event.actor.name, JSON.stringify(event)).toBeTruthy();
    expect(event.actor.id, JSON.stringify(event)).toBeTruthy();
    expect(event.at, JSON.stringify(event)).toBeTruthy();
    const ts = Date.parse(event.at);
    expect(Number.isNaN(ts), `timestamp should parse: ${event.at}`).toBe(false);
    expect(ts, `events should be oldest first: ${JSON.stringify(items)}`).toBeGreaterThanOrEqual(previous);
    previous = ts;
  }
});
